export type Place = {
  id: string;
  name: string;
  category: string;
  subcategory?: string | null; // what it is inside the category (e.g. Other · gym)
  lat: number;
  lon: number;
  address?: string | null;
  website?: string | null;
  phone?: string | null;
  confidence?: number | null; // Overture's data-quality score, 0–1
  source?: string;
  // your personal data, merged in from the DB at runtime:
  note?: string;
  rating?: number | null;
  favourite?: boolean;
};

import imported from "@/data/imported-places.json";

/** Real data, generated by scripts/import-overture.mjs from the Overture export. */
export const places: Place[] = imported as Place[];

/** Great Yarmouth centre — used for map default view and "near me" fallback */
export const GY_CENTRE: [number, number] = [52.6083, 1.7305];

/** Bounding box used by the import scripts (matches the transit filter) */
export const GY_BBOX = { latMin: 52.54, latMax: 52.66, lonMin: 1.67, lonMax: 1.79 };
